css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; }
.loader .balloon { position: absolute; left: 50%; bottom: 22%; width: 48%; height: 54%; margin-left: -24%; background: radial-gradient(circle at 40% 30%, color-mix(in srgb, #fff 35%, var(--accent)), var(--accent) 58%, var(--accent-2)); border-radius: 50% 50% 50% 50% / 44% 44% 64% 64%; animation: hab calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader .balloon::before { content: ''; position: absolute; top: 100%; left: 50%; width: 38%; height: calc(var(--loader-size) * .12); margin-left: -19%; border-left: 2px solid color-mix(in srgb, #000 30%, var(--accent)); border-right: 2px solid color-mix(in srgb, #000 30%, var(--accent)); }
.loader .balloon::after { content: ''; position: absolute; top: 100%; left: 50%; width: 22%; height: 16%; margin-left: -11%; margin-top: calc(var(--loader-size) * .11); background: #92400e; border-radius: 2px 2px 5px 5px; }
@keyframes hab { 0%, 100% { transform: translateY(6%) rotate(-3deg); } 50% { transform: translateY(-9%) rotate(3deg); } }
